-- Booga Booga Hats Unlocker
-- Client-side visual unlocker for all 269 cosmetic hats.
-- Includes exact catalog meshes & textures, custom textures (Love, Lucky, Blood, Bright Horns),
-- 1:1 official Roblox Fedora & Sparkle Time Fedora scaling/attachment, and continuous character sync.

local Players = game:GetService('Players')
local ReplicatedStorage = game:GetService('ReplicatedStorage')
local RunService = game:GetService('RunService')
local CollectionService = game:GetService('CollectionService')

local LocalPlayer = Players.LocalPlayer
local PlayerGui = LocalPlayer:WaitForChild('PlayerGui')

local gameUtil = require(ReplicatedStorage.Modules.util.gameUtil)
local packets = require(ReplicatedStorage.Modules.util.packets)
local itemData = require(ReplicatedStorage.Modules.data.itemData)
local itemIDS = require(ReplicatedStorage.Modules.data.itemIDS)
local colorData = require(ReplicatedStorage.Modules.data.colorData)
local cosmeticsModule = require(ReplicatedStorage.Game.cosmetics)

local GENV = (getgenv and getgenv()) or _G

if GENV.BoogaHatsUnlockerCleanup then
    pcall(GENV.BoogaHatsUnlockerCleanup)
end

local State = {
    connections = {},
    cachedAccessories = {},
    realOwnedHats = GENV.BoogaRealOwnedHats or {},
}
GENV.BoogaCachedAccessories = State.cachedAccessories
GENV.BoogaRealOwnedHats = State.realOwnedHats

if next(State.realOwnedHats) == nil then
    for hatName, owned in pairs(gameUtil.Data.ownedCosmetics or {}) do
        if owned then
            State.realOwnedHats[hatName] = true
        end
    end
end

--------------------------------------------------------------------
-- 1. PHYSICS-SAFE PART SANITIZER
--------------------------------------------------------------------
local ZERO_VEL = Vector3.zero
local LIGHT_PHYS = PhysicalProperties.new(0.01, 0, 0, 0, 0)

local function sanitizeVisualPart(part)
    if not part or not part:IsA('BasePart') then return end
    part.CanCollide = false
    part.CanQuery = false
    part.CanTouch = false
    part.Massless = true
    part.Anchored = false
    part.AssemblyLinearVelocity = ZERO_VEL
    part.AssemblyAngularVelocity = ZERO_VEL
    part.CustomPhysicalProperties = LIGHT_PHYS
    part.LocalTransparencyModifier = 0
end

local function stripNonVisualChildren(inst)
    for _, d in ipairs(inst:GetChildren()) do
        if d:IsA('Sound') or d:IsA('Script') or d:IsA('LocalScript') or d:IsA('TouchTransmitter') then
            d:Destroy()
        end
    end
end

local function createSpecialMeshPart(name, meshId, texId, scale, partSize, vertexColor)
    local p = Instance.new('Part')
    p.Name = name or 'MeshPart'
    p.Size = partSize or Vector3.new(0.4, 0.4, 0.4)
    sanitizeVisualPart(p)
    local sm = Instance.new('SpecialMesh')
    sm.MeshType = Enum.MeshType.FileMesh
    sm.MeshId = meshId
    sm.TextureId = texId or ''
    sm.Scale = scale or Vector3.new(1, 1, 1)
    if vertexColor then
        sm.VertexColor = vertexColor
    end
    sm.Parent = p
    return p, sm
end

--------------------------------------------------------------------
-- 2. HARVEST EXISTING 3D ACCESSORIES IN WORKSPACE
--------------------------------------------------------------------
local function cacheAccessoryInstance(acc)
    if acc and acc:IsA('Accessory') and itemData[acc.Name] and itemData[acc.Name].cosmetic then
        if not acc:GetAttribute('_VisualUnlockedHat') and not State.cachedAccessories[acc.Name] then
            local cl = acc:Clone()
            for _, d in ipairs(cl:GetDescendants()) do
                if d:IsA('RigidConstraint') or d:IsA('Weld') or d:IsA('WeldConstraint') or d:IsA('Motor6D') then
                    d:Destroy()
                elseif d:IsA('BasePart') then
                    sanitizeVisualPart(d)
                end
            end
            State.cachedAccessories[acc.Name] = cl
        end
    end
end

-- 3. THEME & COLOR PALETTE ENGINE
--------------------------------------------------------------------
local function inferThemeColor(name)
    local lower = string.lower(name)
    if string.find(lower, "golden") or string.find(lower, "gold") or string.find(lower, "midas") or string.find(lower, "2026") or string.find(lower, "sun") then
        return Color3.fromRGB(255, 205, 55), Color3.fromRGB(255, 240, 150)
    elseif string.find(lower, "blood") or string.find(lower, "crimson") or string.find(lower, "red") or string.find(lower, "adura") or string.find(lower, "adurite") or string.find(lower, "ruby") or string.find(lower, "santa") or string.find(lower, "festive") or string.find(lower, "inferno") then
        return Color3.fromRGB(230, 45, 50), Color3.fromRGB(120, 15, 20)
    elseif string.find(lower, "void") or string.find(lower, "purple") or string.find(lower, "astral") or string.find(lower, "amethyst") or string.find(lower, "queen") or string.find(lower, "jelly") or string.find(lower, "spooky") or string.find(lower, "nocturnal") or string.find(lower, "kraken") then
        return Color3.fromRGB(170, 55, 255), Color3.fromRGB(65, 20, 110)
    elseif string.find(lower, "emerald") or string.find(lower, "green") or string.find(lower, "lucky") or string.find(lower, "clover") or string.find(lower, "shamrock") or string.find(lower, "patrick") or string.find(lower, "zombie") or string.find(lower, "robux") or string.find(lower, "jungle") or string.find(lower, "celtic") then
        return Color3.fromRGB(55, 230, 95), Color3.fromRGB(25, 110, 45)
    elseif string.find(lower, "blue") or string.find(lower, "aqua") or string.find(lower, "ice") or string.find(lower, "frost") or string.find(lower, "frozen") or string.find(lower, "crystal") or string.find(lower, "diamond") or string.find(lower, "celestial") or string.find(lower, "seaside") or string.find(lower, "skyforged") or string.find(lower, "lapis") or string.find(lower, "splashy") then
        return Color3.fromRGB(75, 205, 255), Color3.fromRGB(30, 95, 185)
    elseif string.find(lower, "pink") or string.find(lower, "valentine") or string.find(lower, "love") or string.find(lower, "heart") or string.find(lower, "bunny") or string.find(lower, "easter") or string.find(lower, "candy") or string.find(lower, "rose") or string.find(lower, "squishy") then
        return Color3.fromRGB(255, 125, 205), Color3.fromRGB(255, 210, 235)
    elseif string.find(lower, "dark") or string.find(lower, "black") or string.find(lower, "shadow") or string.find(lower, "death") or string.find(lower, "obsidian") or string.find(lower, "coal") or string.find(lower, "reaper") or string.find(lower, "phantom") or string.find(lower, "evil") then
        return Color3.fromRGB(45, 45, 55), Color3.fromRGB(140, 40, 200)
    elseif string.find(lower, "white") or string.find(lower, "snow") or string.find(lower, "ghost") or string.find(lower, "heavenly") or string.find(lower, "quartz") or string.find(lower, "silver") or string.find(lower, "light") or string.find(lower, "illuminated") or string.find(lower, "marble") then
        return Color3.fromRGB(245, 248, 255), Color3.fromRGB(195, 215, 240)
    elseif string.find(lower, "orange") or string.find(lower, "pumpkin") or string.find(lower, "fire") or string.find(lower, "flame") or string.find(lower, "magma") or string.find(lower, "hallow") or string.find(lower, "scary") or string.find(lower, "carrot") or string.find(lower, "bronze") or string.find(lower, "giving") then
        return Color3.fromRGB(255, 135, 35), Color3.fromRGB(190, 60, 15)
    elseif string.find(lower, "yellow") or string.find(lower, "barambit") or string.find(lower, "desert") or string.find(lower, "beach") then
        return Color3.fromRGB(255, 230, 55), Color3.fromRGB(200, 150, 30)
    elseif string.find(lower, "chocolate") or string.find(lower, "gingerbread") or string.find(lower, "wood") or string.find(lower, "oak") or string.find(lower, "coconut") or string.find(lower, "banto") or string.find(lower, "turkey") then
        return Color3.fromRGB(150, 95, 55), Color3.fromRGB(95, 55, 30)
    elseif string.find(lower, "patriotic") or string.find(lower, "july") then
        return Color3.fromRGB(80, 150, 255), Color3.fromRGB(240, 50, 50)
    elseif string.find(lower, "disco") or string.find(lower, "rainbow") or string.find(lower, "party") or string.find(lower, "boundless") then
        return Color3.fromRGB(60, 245, 255), Color3.fromRGB(255, 65, 215)
    end
    return Color3.fromRGB(220, 200, 255), Color3.fromRGB(110, 90, 155)
end

-- Softly convert a Color3 into a bright VertexColor multiplier so textures NEVER become muddy or black
local function toBrightVertexColor(c)
    local r = 0.25 + (c.R * 0.85)
    local g = 0.25 + (c.G * 0.85)
    local b = 0.25 + (c.B * 0.85)
    return Vector3.new(math.clamp(r, 0.22, 1.15), math.clamp(g, 0.22, 1.15), math.clamp(b, 0.22, 1.15))
end

--------------------------------------------------------------------
-- 4. CRITTER HAT ("Am ..." & "Inflatable ...") 3D BUILDER
--------------------------------------------------------------------
local function findCritterModel(critterNames)
    local crittersFolder = workspace:FindFirstChild("Critters")
    if not crittersFolder then return nil end
    for _, name in ipairs(critterNames) do
        local found = crittersFolder:FindFirstChild(name)
        if found then return found end
    end
    for _, child in ipairs(crittersFolder:GetChildren()) do
        for _, name in ipairs(critterNames) do
            if string.find(string.lower(child.Name), string.lower(name), 1, true) then
                return child
            end
        end
    end
    return nil
end

local function buildDeployableCompositeHat(hatName, sourceModel, partFilter, scaleMult, yOffset)
    if not sourceModel then return nil end
    local parts = {}
    for _, d in ipairs(sourceModel:GetDescendants()) do
        if d:IsA("BasePart") and (not partFilter or partFilter(d)) then
            table.insert(parts, d)
        end
    end
    if #parts == 0 then return nil end

    local acc = Instance.new("Accessory")
    acc.Name = hatName

    local rootSource = parts[1]
    local rootCF = rootSource.CFrame
    local handle = rootSource:Clone()
    handle.Name = "Handle"
    stripNonVisualChildren(handle)
    sanitizeVisualPart(handle)
    handle.Transparency = 0
    handle.Size = handle.Size * scaleMult
    handle.Parent = acc

    local att = Instance.new("Attachment")
    att.Name = "HatAttachment"
    att.CFrame = CFrame.new(0, yOffset, 0)
    att.Parent = handle

    for i = 2, #parts do
        local child = parts[i]
        local pClone = child:Clone()
        stripNonVisualChildren(pClone)
        sanitizeVisualPart(pClone)
        pClone.Transparency = 0
        pClone.Size = pClone.Size * scaleMult
        local relCF = rootCF:Inverse() * child.CFrame
        relCF = CFrame.new(relCF.Position * scaleMult) * (relCF - relCF.Position)
        pClone.Parent = acc

        local w = Instance.new("Weld")
        w.Name = "CritterHatWeld"
        w.Part0 = handle
        w.Part1 = pClone
        w.C0 = relCF
        w.Parent = handle
    end

    return acc
end

local function buildAmCritterHat(hatName)
    local lower = string.lower(hatName)
    local primary, secondary = inferThemeColor(hatName)
    local isInflatable = string.find(lower, "^inflatable ") ~= nil

    -- Special non-Critter "Am ..." hats
    if hatName == "AM COAL" then
        local acc = Instance.new("Accessory")
        acc.Name = hatName
        local h = State.cachedMeshes["BaseRockUnion"] and State.cachedMeshes["BaseRockUnion"]:Clone() or getOrCreateMeshTemplate("BombBody")
        h.Name = "Handle"
        stripNonVisualChildren(h)
        sanitizeVisualPart(h)
        if h:IsA("UnionOperation") then h.UsePartColor = true end
        h.Color = Color3.fromRGB(28, 28, 32)
        h.Material = Enum.Material.Slate
        h.Size = Vector3.new(1.4, 1.3, 1.4)
        h.Parent = acc
        local att = Instance.new("Attachment")
        att.Name = "HatAttachment"
        att.Position = Vector3.new(0, -0.65, 0)
        att.Parent = h
        return acc
    elseif hatName == "Am Beach Ball" then
        local balloon = ReplicatedStorage.Misc:FindFirstChild("Balloon") and ReplicatedStorage.Misc.Balloon:FindFirstChild("Sphere")
        local acc = Instance.new("Accessory")
        acc.Name = hatName
        local h = balloon and balloon:Clone() or getOrCreateMeshTemplate("BombBody")
        h.Name = "Handle"
        stripNonVisualChildren(h)
        sanitizeVisualPart(h)
        h.Size = Vector3.new(1.45, 1.45, 1.45)
        h.Color = Color3.fromRGB(255, 85, 85)
        h.Material = Enum.Material.SmoothPlastic
        h.Parent = acc
        local att = Instance.new("Attachment")
        att.Name = "HatAttachment"
        att.Position = Vector3.new(0, -0.8, 0)
        att.Parent = h
        return acc
    elseif hatName == "Am Chillman" then
        local snowman = ReplicatedStorage.Deployables:FindFirstChild("Snowman")
        if snowman then
            return buildDeployableCompositeHat(hatName, snowman, function(p)
                return p.Name ~= "Sphere.001" and p.Name ~= "Reference"
            end, 0.72, -0.65)
        end
    elseif hatName == "Am Cooked Turkey" then
        local acc = Instance.new("Accessory")
        acc.Name = hatName
        local h = createSpecialMeshPart("Handle", "http://www.roblox.com/asset?id=153994053", "http://www.roblox.com/asset?id=153994115", Vector3.new(1.35, 1.35, 1.35), Vector3.new(1.2, 1.2, 1.2), Vector3.new(0.95, 0.68, 0.42))
        h.Parent = acc
        local att = Instance.new("Attachment")
        att.Name = "HatAttachment"
        att.Position = Vector3.new(0, -0.65, 0)
        att.Parent = h
        return acc
    elseif hatName == "Am Big Fish" then
        local acc = Instance.new("Accessory")
        acc.Name = hatName
        local h = createSpecialMeshPart("Handle", "http://www.roblox.com/asset/?id=11144802", "http://www.roblox.com/asset/?id=135437303", Vector3.new(1.25, 1.25, 1.25), Vector3.new(1.2, 1.2, 1.2), Vector3.new(0.45, 0.85, 1.0))
        h.Parent = acc
        local att = Instance.new("Attachment")
        att.Name = "HatAttachment"
        att.Position = Vector3.new(0, -0.65, 0)
        att.Parent = h
        return acc
    elseif hatName == "Am Boogian" then
        local acc = Instance.new("Accessory")
        acc.Name = hatName
        local h = Instance.new("Part")
        h.Name = "Handle"
        h.Size = Vector3.new(1.1, 1.1, 1.1)
        h.Color = Color3.fromRGB(234, 184, 146)
        sanitizeVisualPart(h)
        local sm = Instance.new("SpecialMesh")
        sm.MeshType = Enum.MeshType.Head
        sm.Scale = Vector3.new(1.25, 1.25, 1.25)
        sm.Parent = h
        h.Parent = acc
        local att = Instance.new("Attachment")
        att.Name = "HatAttachment"
        att.Position = Vector3.new(0, -0.75, 0)
        att.Parent = h
        return acc
    elseif hatName == "Am Rabbit" or hatName == "Am Snowy Rabbit" then
        local isSnowy = (hatName == "Am Snowy Rabbit")
        local col = isSnowy and Color3.fromRGB(245, 248, 255) or Color3.fromRGB(195, 155, 120)
        local acc = Instance.new("Accessory")
        acc.Name = hatName
        local h = createSpecialMeshPart("Handle", "http://www.roblox.com/asset/?id=1577360", "http://www.roblox.com/asset/?id=1577349", Vector3.new(1.05, 1.25, 1.05), Vector3.new(1.1, 1.1, 1.1), toBrightVertexColor(col))
        h.Parent = acc
        local att = Instance.new("Attachment")
        att.Name = "HatAttachment"
        att.Position = Vector3.new(0, -0.85, 0)
        att.Parent = h
        return acc
    elseif hatName == "Am Pumpkin" then
        local fp = ReplicatedStorage:FindFirstChild("Projectiles") and ReplicatedStorage.Projectiles:FindFirstChild("Fury Pumpkin")
        if fp then
            local acc = Instance.new("Accessory")
            acc.Name = hatName
            local h = fp:Clone()
            h.Name = "Handle"
            stripNonVisualChildren(h)
            sanitizeVisualPart(h)
            h.Size = h.Size * 0.78
            h.Parent = acc
            local att = Instance.new("Attachment")
            att.Name = "HatAttachment"
            att.CFrame = CFrame.new(0, -0.65, 0)
            att.Parent = h
            return acc
        end
    end

    local isNaturalCritterColor = (
        hatName == "Am Banto" or hatName == "Am Golden Banto" or hatName == "Am Shelly" or hatName == "Am Dancing Shelly"
        or hatName == "Am Iron Shelly" or hatName == "Am Gold Shelly" or hatName == "Am Black Ant"
        or hatName == "Am White Ant" or hatName == "Am Fire Ant" or hatName == "Am Huge Ant"
        or hatName == "Am Scavenger" or hatName == "Am Queen Ant" or hatName == "Am Lurky Boi"
        or hatName == "Am Peeper" or hatName == "Am Penguin" or hatName == "Am Turtle"
        or hatName == "Am Mammoth" or hatName == "Am Snowy Mammoth"
        or hatName == "Inflatable Banto" or hatName == "Inflatable Ant" or hatName == "Inflatable Lurky Boi" or hatName == "Inflatable Mammoth"
    )

    local critterModel = nil
    local allowedParts = nil
    local rootPartName = "Head"
    local faceFlipY = 0
    local yOffset = -0.68
    local baseScale = 0.65

    local _, bigCount = string.gsub(hatName, "BIG:", "")
    local bigMult = 1.0 + (bigCount * 0.55)

    if string.find(lower, "shelly") then
        if string.find(lower, "iron") then
            critterModel = findCritterModel({"Iron Shelly", "Stone Shelly", "Gold Shelly"})
        elseif string.find(lower, "gold") then
            critterModel = findCritterModel({"Gold Shelly", "Iron Shelly", "Stone Shelly"})
        else
            critterModel = findCritterModel({"Stone Shelly", "Iron Shelly", "Gold Shelly", "Shelly Spirit"})
        end
        rootPartName = "Shell"
        allowedParts = { Shell = true, Head = true }
        baseScale = 0.68
        yOffset = -0.68
    elseif string.find(lower, "banto") then
        if string.find(lower, "golden") then
            critterModel = findCritterModel({"Golden Banto", "Banto", "Rento", "Bantae"})
        else
            critterModel = findCritterModel({"Banto", "Golden Banto", "Bantae", "Lil Banto"})
        end
        rootPartName = "Head"
        allowedParts = { Head = true, Eye = true, Antlers = true }
        baseScale = 0.58
        yOffset = -0.68
    elseif string.find(lower, "queen ant") then
        critterModel = findCritterModel({"Queen Ant's Servant", "Queen Ant", "White Ant", "Black Ant"})
        rootPartName = "Head"
        allowedParts = {
            Head = true, Eye = true, Eye2 = true,
            Antennae = true, Antennae2 = true, Antennae1 = true, AntennaeMid1 = true, AntennaeMid2 = true, AntennaeEnd1 = true, AntennaeEnd2 = true,
            Mouthpart1 = true, Mouthpart2 = true, Mouthpart3 = true, Mouthpart4 = true, Mouthpart1End = true, Mouthpart2End = true,
        }
        faceFlipY = math.pi
        baseScale = 0.60
        yOffset = -0.65
    elseif string.find(lower, "ant") or string.find(lower, "scavenger") then
        if string.find(lower, "fire") then
            critterModel = findCritterModel({"Fire Ant", "Black Ant", "White Ant", "Scavenger Ant"})
        elseif string.find(lower, "white") then
            critterModel = findCritterModel({"White Ant", "Black Ant", "Fire Ant", "Scavenger Ant"})
        elseif string.find(lower, "huge") then
            critterModel = findCritterModel({"Huge Ant", "Black Ant", "White Ant"})
        elseif string.find(lower, "scavenger") then
            critterModel = findCritterModel({"Scavenger Ant", "Black Ant", "White Ant"})
        else
            critterModel = findCritterModel({"Black Ant", "White Ant", "Fire Ant", "Scavenger Ant"})
        end
        rootPartName = "Head"
        allowedParts = {
            Head = true, Eye = true, Eye2 = true,
            Antennae = true, Antennae2 = true, Antennae1 = true, AntennaeMid1 = true, AntennaeMid2 = true, AntennaeEnd1 = true, AntennaeEnd2 = true,
            Mouthpart1 = true, Mouthpart2 = true, Mouthpart3 = true, Mouthpart4 = true, Mouthpart1End = true, Mouthpart2End = true,
        }
        faceFlipY = math.pi
        baseScale = 0.62
        yOffset = -0.65
    elseif string.find(lower, "mammoth") then
        if string.find(lower, "snow") then
            critterModel = findCritterModel({"Snow Mammoth", "Baby Sand Mammoth", "Sand Mammoth"})
        else
            critterModel = findCritterModel({"Baby Sand Mammoth", "Sand Mammoth", "Snow Mammoth"})
        end
        if critterModel and critterModel.Name == "Baby Sand Mammoth" then
            baseScale = 0.58
        else
            baseScale = 0.28
        end
        rootPartName = "Head"
        allowedParts = { Head = true, Eye = true, Tusk = true, Trunk = true }
        yOffset = -0.72
    elseif string.find(lower, "lurky") or string.find(lower, "goldy") then
        critterModel = findCritterModel({"Lurky Boi"})
        rootPartName = "Head"
        allowedParts = { Head = true }
        baseScale = 0.55
        yOffset = -0.65
    elseif string.find(lower, "peeper") then
        critterModel = findCritterModel({"Peeper", "Bird"})
        rootPartName = "Head"
        allowedParts = { Head = true, Eye = true, Eye2 = true, Beak = true, Warble = true }
        baseScale = 0.68
        yOffset = -0.62
    elseif string.find(lower, "penguin") then
        critterModel = findCritterModel({"Penguin"})
        rootPartName = "Head"
        allowedParts = { Head = true, ["Left Eye"] = true, ["Right Eye"] = true, Beak = true }
        faceFlipY = math.pi
        baseScale = 0.65
        yOffset = -0.65
    elseif string.find(lower, "turtle") then
        critterModel = findCritterModel({"Turtle"})
        rootPartName = "Shell"
        allowedParts = { Shell = true, base = true, Head = true }
        faceFlipY = -math.pi / 2
        baseScale = 0.62
        yOffset = -0.65
    end

    if not critterModel then
        return nil
    end

    local sourceRoot = critterModel:FindFirstChild(rootPartName) or critterModel:FindFirstChild("Head") or critterModel:FindFirstChild("Shell")
    if not (sourceRoot and sourceRoot:IsA("BasePart")) then
        return nil
    end

    local finalScale = baseScale * bigMult
    local acc = Instance.new("Accessory")
    acc.Name = hatName
    if string.find(lower, "dancing shelly") then
        CollectionService:AddTag(acc, "DancingShellyHat")
    end

    local rootCF = sourceRoot.CFrame
    local handle = sourceRoot:Clone()
    handle.Name = "Handle"
    stripNonVisualChildren(handle)
    sanitizeVisualPart(handle)
    handle.Transparency = 0
    handle.Size = handle.Size * finalScale

    if isInflatable then
        handle.Material = Enum.Material.SmoothPlastic
        handle.Reflectance = 0.15
    elseif not isNaturalCritterColor or string.find(lower, "goldy") or (string.find(lower, "queen ant") and critterModel.Name ~= "Queen Ant") then
        if handle:IsA("UnionOperation") then
            handle.UsePartColor = true
        end
        handle.Color = primary
        if string.find(lower, "jelly") or string.find(lower, "crystal") then
            handle.Material = Enum.Material.Glass
            handle.Transparency = 0.18
        elseif string.find(lower, "god") or string.find(lower, "void") or string.find(lower, "skyforged") then
            handle.Material = Enum.Material.Neon
        elseif string.find(lower, "gold") then
            handle.Material = Enum.Material.Metal
        end
    end
    handle.Parent = acc

    local att = Instance.new("Attachment")
    att.Name = "HatAttachment"
    att.CFrame = CFrame.new(0, yOffset * bigMult, 0) * CFrame.Angles(0, faceFlipY, 0)
    att.Parent = handle

    for _, child in ipairs(critterModel:GetChildren()) do
        if child:IsA("BasePart") and child ~= sourceRoot and (not allowedParts or allowedParts[child.Name]) then
            local pClone = child:Clone()
            stripNonVisualChildren(pClone)
            sanitizeVisualPart(pClone)
            pClone.Transparency = 0
            pClone.Size = pClone.Size * finalScale

            if isInflatable then
                pClone.Material = Enum.Material.SmoothPlastic
                pClone.Reflectance = 0.15
            elseif (not isNaturalCritterColor or (string.find(lower, "queen ant") and critterModel.Name ~= "Queen Ant"))
                and (child.Name == "Head" or string.find(child.Name, "Antenna") or child.Name == "Trunk" or child.Name == "Antlers") then
                if pClone:IsA("UnionOperation") then
                    pClone.UsePartColor = true
                end
                pClone.Color = (child.Name == "Antlers") and secondary or primary
            end

            local relCF = rootCF:Inverse() * child.CFrame
            relCF = CFrame.new(relCF.Position * finalScale) * (relCF - relCF.Position)
            pClone.Parent = acc

            local w = Instance.new("Weld")
            w.Name = "CritterHatWeld"
            w.Part0 = handle
            w.Part1 = pClone
            w.C0 = relCF
            w.Parent = handle
        end
    end

    return acc
end

