-- 5. EXACT CATALOG & PRIVATE HAT RECONSTRUCTION (ZERO TEXTURE STRIPPING)
--------------------------------------------------------------------
local function createCustomMeshAccessory(hatName, meshId, texId, scale, attCFrame, vertexColor, extraFn)
    local acc = Instance.new("Accessory")
    acc.Name = hatName
    local handle, sm = createSpecialMeshPart("Handle", meshId, texId, scale or Vector3.new(1, 1, 1), Vector3.new(1, 1, 1), vertexColor)
    handle.Parent = acc

    local att = Instance.new("Attachment")
    att.Name = "HatAttachment"
    att.CFrame = attCFrame or CFrame.new(0, -0.45, 0)
    att.Parent = handle

    if extraFn then
        pcall(extraFn, acc, handle, sm)
    end
    return acc
end

local function attachBunnyEarsSubpart(acc, handle, earVertexColor, offsetCF)
    local ears = createSpecialMeshPart(
        "BunnyEarsPart",
        "http://www.roblox.com/asset/?id=1577360",
        "http://www.roblox.com/asset/?id=1577349",
        Vector3.new(1.0, 1.25, 1.0),
        Vector3.new(0.5, 0.5, 0.5),
        earVertexColor or Vector3.new(1, 0.85, 0.92)
    )
    ears.Parent = acc
    local w = Instance.new("Weld")
    w.Name = "CritterHatWeld"
    w.Part0 = handle
    w.Part1 = ears
    w.C0 = offsetCF or CFrame.new(0, 0.75, 0)
    w.Parent = handle
end

local function buildHatAccessory(hatName)
    if State.cachedAccessories[hatName] then
        return State.cachedAccessories[hatName]:Clone()
    end

    local lower = string.lower(hatName)

    -- 1. First check if it's an "Am ..." or "Inflatable ..." Critter Hat
    if string.find(lower, "^am ") or string.find(lower, ": am ") or string.find(lower, "^inflatable ") or hatName == "AM COAL" then
        local critterAcc = buildAmCritterHat(hatName)
        if critterAcc then
            State.cachedAccessories[hatName] = critterAcc:Clone()
            return critterAcc
        end
    end

    -- 2. Try loading from itemData[hatName].image aid if it is one of the 90 Public Roblox Accessories
    local data = itemData[hatName]
    local aid = data and data.image and string.match(data.image, "aid=(%d+)")
    if aid then
        local ok, objs = pcall(function()
            return game:GetObjects("rbxassetid://" .. tostring(aid))
        end)
        if ok and objs and #objs > 0 then
            local obj = objs[1]
            if obj:IsA("Accessory") then
                obj.Name = hatName
                obj:SetAttribute("_VisualUnlockedHat", true)
                for _, d in ipairs(obj:GetDescendants()) do
                    if d:IsA("BasePart") then
                        sanitizeVisualPart(d)
                    end
                end
                local hPart = obj:FindFirstChild("Handle")
                if hPart then
                    if hatName == "The Flaming Horns" or hatName == "FrozenHorns1" or hatName == "PoisonHorns1" then
                        -- Remove any stray particle emitters
                        for _, p in ipairs(hPart:GetChildren()) do
                            if p:IsA("ParticleEmitter") then p:Destroy() end
                        end
                        local fire = hPart:FindFirstChildOfClass("Fire")
                        if not fire then
                            fire = Instance.new("Fire")
                            fire.Parent = hPart
                        end
                        fire.Size = 3
                        fire.Heat = 8
                        if hatName == "The Flaming Horns" then
                            fire.Color = Color3.fromRGB(236, 139, 70)
                            fire.SecondaryColor = Color3.fromRGB(139, 80, 55)
                        elseif hatName == "FrozenHorns1" then
                            fire.Color = Color3.fromRGB(52, 206, 236)
                            fire.SecondaryColor = Color3.fromRGB(2, 64, 139)
                        elseif hatName == "PoisonHorns1" then
                            fire.Color = Color3.fromRGB(91, 222, 68)
                            fire.SecondaryColor = Color3.fromRGB(0, 85, 0)
                        end
                    end
                end
                local _, bigCount = string.gsub(hatName, "BIG:", "")
                if bigCount > 0 then
                    local mult = 1.0 + (bigCount * 0.65)
                    for _, d in ipairs(obj:GetDescendants()) do
                        if d:IsA("SpecialMesh") then
                            d.Scale = d.Scale * mult
                        elseif d:IsA("BasePart") then
                            d.Size = d.Size * mult
                        end
                    end
                end
                State.cachedAccessories[hatName] = obj:Clone()
                return obj
            elseif obj:IsA("BasePart") then
                local acc = Instance.new("Accessory")
                acc.Name = hatName
                acc:SetAttribute("_VisualUnlockedHat", true)
                obj.Name = "Handle"
                sanitizeVisualPart(obj)
                obj.Parent = acc
                if not obj:FindFirstChildOfClass("Attachment") then
                    local att = Instance.new("Attachment")
                    att.Name = "HatAttachment"
                    att.Position = Vector3.new(0, -0.5, 0)
                    att.Parent = obj
                end
                State.cachedAccessories[hatName] = acc:Clone()
                return acc
            end
        end
    end

    -- 3. Exact Family-Based 3D Mesh + Texture Mapping for all 133 non-Critter Private Hats
    local primary, secondary = inferThemeColor(hatName)
    local vColor = toBrightVertexColor(primary)
    local acc = nil

    -- A. Gold Pot Hats (built from ReplicatedStorage.Deployables["Pot o' Gold"] / "Golden Gold Pot")
    if string.find(lower, "gold pot") or string.find(lower, "pot o' gold") then
        local potModel = string.find(lower, "golden") and ReplicatedStorage.Deployables:FindFirstChild("Golden Gold Pot")
            or ReplicatedStorage.Deployables:FindFirstChild("Pot o' Gold")
            or ReplicatedStorage.Deployables:FindFirstChild("Gold Pot")
        acc = buildDeployableCompositeHat(hatName, potModel, function(p)
            return p:IsA("MeshPart") and p.Name ~= "Reference"
        end, 0.42, -0.45)

    -- B. Tree Head & Ancient Tree Head (built from ReplicatedStorage.Deployables["Hammock on Palm"])
    elseif string.find(lower, "tree head") then
        local palm = ReplicatedStorage.Deployables:FindFirstChild("Hammock on Palm")
        acc = buildDeployableCompositeHat(hatName, palm, function(p)
            return string.find(p.Name, "Tiny_Palm_Tree") ~= nil
        end, 0.22, -0.55)
        if acc and string.find(lower, "ancient") then
            for _, d in ipairs(acc:GetDescendants()) do
                if d:IsA("BasePart") and string.find(d.Name, "Leaves") then
                    d.Color = Color3.fromRGB(85, 220, 255)
                    d.Material = Enum.Material.Neon
