            -- Base64 Decoder & Universal Embedded Assets
local b64chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local b64lookup = {}
for i = 1, 64 do b64lookup[b64chars:sub(i, i)] = i - 1 end

local function luaBase64Decode(data)
    data = data:gsub('[^'..b64chars..'=]', '')
    local result = {}
    local len = #data
    for i = 1, len, 4 do
        local c1 = b64lookup[data:sub(i, i)] or 0
        local c2 = b64lookup[data:sub(i+1, i+1)] or 0
        local c3 = b64lookup[data:sub(i+2, i+2)] or 0
        local c4 = b64lookup[data:sub(i+3, i+3)] or 0
        local n = (c1 * 262144) + (c2 * 4096) + (c3 * 64) + c4
        table.insert(result, string.char(math.floor(n / 65536) % 256))
        if data:sub(i+2, i+2) ~= '=' then
            table.insert(result, string.char(math.floor(n / 256) % 256))
        end
        if data:sub(i+3, i+3) ~= '=' then
            table.insert(result, string.char(n % 256))
        end
    end
    return table.concat(result)
end

local function decodeB64(str)
    if crypt and crypt.base64decode then return crypt.base64decode(str) end
    if crypt and crypt.base64_decode then return crypt.base64_decode(str) end
    if base64_decode then return base64_decode(str) end
    if syn and syn.crypt and syn.crypt.base64 and syn.crypt.base64.decode then return syn.crypt.base64.decode(str) end
    return luaBase64Decode(str)
end

