        '',
    },
}

local function ensureCustomAsset(filename, fallback)
    local hasCustom = (getcustomasset ~= nil)
    local hasWrite = (writefile ~= nil)
    local hasIsfile = (isfile ~= nil)

    if hasCustom and hasWrite then
        local exists = false
        if hasIsfile then
            local s, res = pcall(isfile, filename)
            exists = (s and res == true)
        end

        if not exists and EMBEDDED_ASSETS[filename] then
            pcall(function()
                local fullB64 = table.concat(EMBEDDED_ASSETS[filename])
                local decoded = decodeB64(fullB64)
                writefile(filename, decoded)
            end)
        end

        local ok, asset = pcall(getcustomasset, filename)
        if ok and asset and asset ~= '' then
            return asset
        end
    end
    return fallback
end


