    elseif hatName == "Skull Helmet" then
        acc = createCustomMeshAccessory(hatName, "http://www.roblox.com/asset/?id=61901939", "http://www.roblox.com/asset/?id=61901998", Vector3.new(1.05, 1.05, 1.05), CFrame.new(0, -0.25, 0))
    elseif hatName == "Phantom Skull" then
        acc = createCustomMeshAccessory(hatName, "http://www.roblox.com/asset/?id=74890783", "http://www.roblox.com/asset/?id=74890724", Vector3.new(1.05, 1.05, 1.05), CFrame.new(0, -0.25, 0), Vector3.new(0.65, 0.85, 1.15))
    elseif hatName == "Old God Mask" then
        acc = createCustomMeshAccessory(hatName, "http://www.roblox.com/asset/?id=15881174", "http://www.roblox.com/asset/?id=15881163", Vector3.new(1.08, 1.08, 1.08), CFrame.new(0, -0.2, 0), Vector3.new(0.75, 0.85, 1.1))
    elseif hatName == "Fury" then
        acc = createCustomMeshAccessory(hatName, "http://www.roblox.com/asset/?id=93129244", "http://www.roblox.com/asset/?id=93129336", Vector3.new(1.05, 1.05, 1.05), CFrame.new(0, -0.25, 0), Vector3.new(1.1, 0.55, 0.35))
    elseif hatName == "Woken" then
        acc = createCustomMeshAccessory(hatName, "http://www.roblox.com/asset/?id=170786715", "http://www.roblox.com/asset/?id=170786742", Vector3.new(1.05, 1.05, 1.05), CFrame.new(0, -0.25, 0), Vector3.new(0.85, 0.95, 1.15))
    end

    if not acc then
        acc = createCustomMeshAccessory(hatName, "http://www.roblox.com/asset/?id=1078075", "http://www.roblox.com/asset/?id=1078071", Vector3.new(1, 1, 1), CFrame.new(0, -0.5, 0), vColor)
    end

    acc.Name = hatName
    State.cachedAccessories[hatName] = acc:Clone()
    return acc
end

--------------------------------------------------------------------
-- 6. PHYSICS-SAFE SINGLE-JOINT HAT ATTACHMENT
--------------------------------------------------------------------
local function attachHatToCharacter(char, hatName)
    if not char then return end
    local head = char:FindFirstChild("Head")
    if not head then return end

    for _, child in ipairs(char:GetChildren()) do
        if child:IsA("Accessory") and child.Name == hatName then
            child:Destroy()
        end
    end

    if hatName == "Headless Head" then
        head.Transparency = 1
        for _, d in ipairs(head:GetChildren()) do
            if d:IsA("Decal") then
                d.Transparency = 1
            end
        end
    end

    local acc = buildHatAccessory(hatName)
    if not acc then return end
    acc.Name = hatName
    acc:SetAttribute("_VisualUnlockedHat", true)

    local handle = acc:FindFirstChild("Handle")
    if not handle then
        acc:Destroy()
        return
    end

    for _, part in ipairs(acc:GetDescendants()) do
        if part:IsA("BasePart") then
            sanitizeVisualPart(part)
            if part.Transparency >= 1 then
                part.Transparency = 0
            end
        end
    end

    local accAtt = handle:FindFirstChildOfClass("Attachment")
    if not accAtt then
        accAtt = Instance.new("Attachment")
        accAtt.Name = "HatAttachment"
        accAtt.Position = Vector3.new(0, -0.5, 0)
        accAtt.Parent = handle
    end

    local targetPart = head
    local targetAtt = head:FindFirstChild(accAtt.Name)
    if not targetAtt and char:FindFirstChild("UpperTorso") then
        local torsoAtt = char.UpperTorso:FindFirstChild(accAtt.Name)
        if torsoAtt then
            targetPart = char.UpperTorso
            targetAtt = torsoAtt
        end
    end
    if not targetAtt then
        targetAtt = head:FindFirstChild("HatAttachment")
    end

    -- Clean up any existing constraints/welds on handle (except CritterHatWeld sub-part welds)
    for _, c in ipairs(handle:GetChildren()) do
        if (c:IsA("RigidConstraint") or c:IsA("Weld") or c:IsA("WeldConstraint")) and c.Name ~= "CritterHatWeld" then
            c:Destroy()
        end
    end

    -- Position handle at exact target CFrame before parenting so there is zero physics snap
    if targetAtt then
        handle.CFrame = targetPart.CFrame * targetAtt.CFrame * accAtt.CFrame:Inverse()
    else
        handle.CFrame = targetPart.CFrame * CFrame.new(0, 0.6, 0) * accAtt.CFrame:Inverse()
    end

    acc.Parent = char

    -- IMPORTANT: Use ONLY ONE joint type! Never create both Weld and RigidConstraint simultaneously!
    if CollectionService:HasTag(acc, "DancingShellyHat") and targetAtt then
        local rc = Instance.new("RigidConstraint")
        rc.Name = "AccessoryRigidConstraint"
        rc.Attachment0 = accAtt
        rc.Attachment1 = targetAtt
        rc.Parent = handle
    else
        local w = Instance.new("Weld")
        w.Name = "AccessoryWeld"
        w.Part0 = targetPart
        w.Part1 = handle
        if targetAtt then
            w.C0 = targetAtt.CFrame
            w.C1 = accAtt.CFrame
        else
            w.C0 = CFrame.new(0, 0.6, 0)
            w.C1 = accAtt.CFrame
        end
        w.Parent = handle
    end
end

local function removeHatFromCharacter(char, hatName)
    if not char then return end
    for _, child in ipairs(char:GetChildren()) do
        if child:IsA("Accessory") and child.Name == hatName then
            child:Destroy()
        end
    end
    if hatName == "Headless Head" then
        local head = char:FindFirstChild("Head")
        if head then
            head.Transparency = 0
            for _, d in ipairs(head:GetChildren()) do
                if d:IsA("Decal") then
                    d.Transparency = 0
                end
            end
        end
    end
end

local function syncAllEquippedHatsOnCharacter(char)
    if not char then return end
    local head = char:FindFirstChild("Head")
    if not head then return end

    local wornSet = {}
    for _, hatName in ipairs(gameUtil.Data.appearance.hats or {}) do
        wornSet[hatName] = true
        local existing = char:FindFirstChild(hatName)
        if not existing then
            attachHatToCharacter(char, hatName)
        else
            local h = existing:FindFirstChild("Handle")
            if h and h.LocalTransparencyModifier ~= 0 then
                h.LocalTransparencyModifier = 0
            end
        end
    end

    for _, child in ipairs(char:GetChildren()) do
        if child:IsA("Accessory") and child:GetAttribute("_VisualUnlockedHat") and not wornSet[child.Name] then
            child:Destroy()
        end
    end
end


--------------------------------------------------------------------
-- 7. UNLOCK ALL 269 HATS IN SHOP -> COSMETICS UI
--------------------------------------------------------------------
local unlockedHatCount = 0
for hatName, data in pairs(itemData) do
    if type(data) == 'table' and data.cosmetic then
        pcall(function()
            cosmeticsModule.cosmeticAdded(hatName)
            unlockedHatCount = unlockedHatCount + 1
        end)
    end
end

--------------------------------------------------------------------
-- 8. HOOK PACKET (EquipCosmetic) + COSMETIC UI SYNC
--------------------------------------------------------------------
local origEquipCosmeticSend = packets.EquipCosmetic.send
local origCosmeticEquipped = cosmeticsModule.cosmeticEquipped
local origCosmeticUnequipped = cosmeticsModule.cosmeticUnequipped

local CosmeticList = PlayerGui.MainGui.LeftPanel.Shop.Lists.CosmeticList
local MAX_VISUAL_HATS = 3

cosmeticsModule.cosmeticUnequipped = function(hatName)
    local frame = CosmeticList:FindFirstChild(hatName)
    if frame then
        frame.TextButton.BackgroundColor3 = colorData.goodGreen
        frame.ItemNameLabel.TextColor3 = colorData.goodGreen
        frame.TextButton.Text = 'WEAR'
    end
    local hats = gameUtil.Data.appearance.hats
    local idx = table.find(hats, hatName)
    while idx do
        table.remove(hats, idx)
        idx = table.find(hats, hatName)
    end
    local char = LocalPlayer.Character or (workspace:FindFirstChild('Players') and workspace.Players:FindFirstChild(LocalPlayer.Name))
    if char then
        removeHatFromCharacter(char, hatName)
    end
end

cosmeticsModule.cosmeticEquipped = function(hatName)
    local hats = gameUtil.Data.appearance.hats
    while #hats >= MAX_VISUAL_HATS do
        local oldest = hats[#hats]
        if oldest then
            cosmeticsModule.cosmeticUnequipped(oldest)
        else
            break
        end
    end

    local frame = CosmeticList:FindFirstChild(hatName)
    if frame then
        frame.ItemNameLabel.TextColor3 = colorData.badRed
        frame.TextButton.BackgroundColor3 = colorData.badRed
        frame.TextButton.Text = 'TAKE OFF'
    end
    if not table.find(hats, hatName) then
        table.insert(hats, 1, hatName)
    end
    local char = LocalPlayer.Character or (workspace:FindFirstChild('Players') and workspace.Players:FindFirstChild(LocalPlayer.Name))
    if char then
        attachHatToCharacter(char, hatName)
    end
end

packets.EquipCosmetic.send = function(cosmeticId)
    local hatName = itemIDS[cosmeticId]
    if not hatName then
        return origEquipCosmeticSend(cosmeticId)
    end

    local isWorn = table.find(gameUtil.Data.appearance.hats, hatName) ~= nil
    if isWorn then
        cosmeticsModule.cosmeticUnequipped(hatName)
    else
        cosmeticsModule.cosmeticEquipped(hatName)
    end
end

-- Rebuild currently worn hats
do
    local initChar = LocalPlayer.Character or (workspace:FindFirstChild('Players') and workspace.Players:FindFirstChild(LocalPlayer.Name))
    if initChar then
        for _, ch in ipairs(initChar:GetChildren()) do
            if ch:IsA('Accessory') and ch:GetAttribute('_VisualUnlockedHat') then
                ch:Destroy()
            end
        end
    end
    local currentHats = {}
    for _, h in ipairs(gameUtil.Data.appearance.hats or {}) do
        if #currentHats < MAX_VISUAL_HATS and not table.find(currentHats, h) then
            table.insert(currentHats, h)
        end
    end
    for _, frame in ipairs(CosmeticList:GetChildren()) do
        if frame:IsA('Frame') and frame:FindFirstChild('TextButton') and frame:FindFirstChild('ItemNameLabel') then
            frame.TextButton.BackgroundColor3 = colorData.goodGreen
            frame.ItemNameLabel.TextColor3 = colorData.goodGreen
            frame.TextButton.Text = 'WEAR'
        end
    end
    table.clear(gameUtil.Data.appearance.hats)
    for i = #currentHats, 1, -1 do
        cosmeticsModule.cosmeticEquipped(currentHats[i])
    end
end

--------------------------------------------------------------------
-- 9. RAINBOW ACCESSORIES LOOP & CHARACTER SYNC
--------------------------------------------------------------------
local lastTrailColorTick = 0
local function applyRainbowColorToHierarchy(rootInst, hsvColor, hsvSecondary, hsvVertex, updateTrails)
    for _, d in ipairs(rootInst:GetDescendants()) do
        if d:IsA('BasePart') and d.Name ~= 'Handle' and not d:GetAttribute('_KeepGripColor') then
            d.Color = hsvColor
        elseif d:IsA('SpecialMesh') then
            d.VertexColor = hsvVertex
        elseif d:IsA('Fire') then
            d.Color = hsvColor
            d.SecondaryColor = hsvSecondary
        elseif updateTrails and (d:IsA('Trail') or d:IsA('ParticleEmitter')) then
            d.Color = ColorSequence.new(hsvColor, hsvSecondary)
        end
    end
end

table.insert(State.connections, RunService.RenderStepped:Connect(function()
    local char = LocalPlayer.Character or (workspace:FindFirstChild('Players') and workspace.Players:FindFirstChild(LocalPlayer.Name))
    if not char then return end
    local now = os.clock()
    local hue = (now * 0.45) % 1
    local hsvColor = Color3.fromHSV(hue, 0.88, 1)
    local hsvSecondary = Color3.fromHSV((hue + 0.35) % 1, 0.85, 1)
    local hsvVertex = Vector3.new(0.25 + hsvColor.R * 0.90, 0.25 + hsvColor.G * 0.90, 0.25 + hsvColor.B * 0.90)
    local updateTrails = (now - lastTrailColorTick) >= 0.08
    if updateTrails then lastTrailColorTick = now end
    for _, child in ipairs(char:GetChildren()) do
        if child:IsA('Accessory') and child:GetAttribute('_IsRainbowVisual') then
            applyRainbowColorToHierarchy(child, hsvColor, hsvSecondary, hsvVertex, updateTrails)
        end
    end
end))

local lastSyncTick = 0
table.insert(State.connections, RunService.Heartbeat:Connect(function()
    local now = os.clock()
    if now - lastSyncTick < 0.25 then return end
    lastSyncTick = now
    local char = LocalPlayer.Character or (workspace:FindFirstChild('Players') and workspace.Players:FindFirstChild(LocalPlayer.Name))
    if char and char:FindFirstChild('Head') then
        syncAllEquippedHatsOnCharacter(char)
    end
end))

local function setupCharacterHats(char)
    if not char then return end
    task.spawn(function()
        local head = char:WaitForChild('Head', 30)
        if head then
            syncAllEquippedHatsOnCharacter(char)
        end
    end)
end

if LocalPlayer.Character then setupCharacterHats(LocalPlayer.Character) end
table.insert(State.connections, LocalPlayer.CharacterAdded:Connect(setupCharacterHats))
table.insert(State.connections, LocalPlayer:GetAttributeChangedSignal('hasSpawned'):Connect(function()
    if LocalPlayer:GetAttribute('hasSpawned') and LocalPlayer.Character then
        setupCharacterHats(LocalPlayer.Character)
    end
end))

GENV.BoogaHatsUnlockerCleanup = function()
    packets.EquipCosmetic.send = origEquipCosmeticSend
    cosmeticsModule.cosmeticEquipped = origCosmeticEquipped
    cosmeticsModule.cosmeticUnequipped = origCosmeticUnequipped
    for _, conn in ipairs(State.connections) do
        if conn.Connected then conn:Disconnect() end
    end
end

print(string.format('[BoogaHatsUnlocker] Ready! Unlocked %d Cosmetics (Hats).', unlockedHatCount))
